<h1><?= e(t('Import / export workspace records')) ?></h1><section class="card"><p><?= e(t('Map your Excel, Notion CSV, Todoist CSV or JSON columns to the selected record type. Existing records stay untouched. The preview shows exactly what will be added.')) ?></p><form class="form-grid" method="post" action="/platform/records/map" enctype="multipart/form-data"><?= csrf_field() ?><label><?= e(t('Destination')) ?><select name="target" required><?php foreach(PortableRecords::targets()as $key=>$t):if(!module_enabled($t['module']))continue; ?><option value="<?= e($key) ?>"><?= e($t['label']) ?></option><?php endforeach; ?></select></label><label><?= e(t('Format')) ?><select name="format"><option value="csv"><?= e(t('CSV')) ?></option><option value="xlsx"><?= e(t('Excel XLSX')) ?></option><option value="notion"><?= e(t('Notion CSV')) ?></option><option value="todoist"><?= e(t('Todoist CSV')) ?></option><option value="json"><?= e(t('JSON')) ?></option></select></label><label><?= e(t('Excel file')) ?><input type="file" name="file" accept=".xlsx"></label><label class="full"><?= e(t('CSV or JSON content')) ?><textarea name="content" rows="6" maxlength="2097152"></textarea></label><button><?= e(t('Choose field mappings')) ?></button></form></section><section class="card"><h2><?= e(t('Portable exports')) ?></h2><?php foreach(PortableRecords::targets()as $key=>$t):if(!module_enabled($t['module']))continue; ?><p><a href="/platform/records/<?= e($key) ?>/export"><?= e($t['label']) ?> <?= e(t('CSV')) ?></a></p><?php endforeach; ?><a href="/platform"><?= e(t('Devices & privacy')) ?></a></section>
